下列给定程序中，函数fun的功能是：把形参a所指数组中的最小值放在元素a[0]中，接着把a所指数组中的最大值放在a[1]元素中;再把a所指数组元素中的次小值放在a[2]中，把a索取数组元素中的次大值放在a[3]，以此类推。 <br> 例如:若a所指数组中的数据最初排列为：9,1,4,2,3,6,5,8,7;按规则移动后，数据排列为:1,9,2,8,3,7,4,6,5。形参n中存放a所指数组中数据的个数。<br> 规定fun函数中的max存放的当前所找的最大值,px存放当前所找最大值得下标。 请在程序的下画线处填入正确的内容并将下画线删除，使程序得出正确的结果。 <br> <div>  试题程序。 <pre class="prettyprint lang-cpp">#include &lt;stdio.h&gt;
#define N 9
void fun(int a[], int n) {
    int i, j, max, min, px, pn, t;
    for (i = 0; i &lt; n - 1; i += 2) {

        max = min = __;
        px = pn = i;
        for (j = i + 1; j &lt; n; j++) {

            if (max &lt; __) {
                max = a[j];
                px = j;
            }

            if (min &gt; __) {
                min = a[j];
                pn = j;
            }
        }
        if (pn != i) {
            t = a[i];
            a[i] = min;
            a[pn] = t;
            if (px == i)
                px = pn;
        }
        if (px != i + 1) {
            t = a[i + 1];
            a[i + 1] = max;
            a[px] = t;
        }
    }
}
int main() {
    int b[N] = {9, 1, 4, 2, 3, 6, 5, 8, 7};
    printf(&quot;\nThe original data:\n&quot;);
    for (int i = 0; i &lt; N; i++)
        printf(&quot;% 4d&quot;, b[i]);
    printf(&quot;\n&quot;);
    fun(b, N);
    printf(&quot;\nThe data after mocinng \n&quot;);
    for (int i = 0; i &lt; N; i++)
        printf(&quot;% 4d&quot;, b[i]);
    printf(&quot;\n&quot;);
    return 0;
}</pre> <br> </div> <br>

下列给定程序中，函数fun的功能是：求ss所指字符串数组中长度最短的字符串所在的行下标，作为函数值返回，并把其串长放在形参n所指的变量中。ss所指字符串数数组中共有M个字符串，且串长小于N。 <br> 请在程序的下画线处填入正确的内容并将下画线删除，使程序得出正确的结果。 <br> <div>  试题程序。 </div> <div> <pre class="prettyprint lang-cpp">#define M 5
#define N 20
int fun(char (*ss)[N], int *n) {
    int i, k = 0, len = N;
    for (i = 0; i &lt; ______; i++) {
        len = strlen(ss[i]);
        if (i == 0)
            *n = len;
        if (len ____ * n) {
            *n = len;
            k = i;
        }
    }
    return (_____);
}
main() {
    char ss[M][N] = {&quot;shanghai&quot;, &quot;guangzhou&quot;, &quot;beijing&quot;, &quot;tianjing&quot;,
                     &quot;chongqing&quot;};
    int n, k, i;
    printf(&quot;\nThe originalb stringsare:\n&quot;);
    for (i = 0; i &lt; M; i++)
        puts(ss[i]);
    k = fun(ss, &amp;n);
    printf(&quot;\nThe length of shortest string is: % d\n&quot;, n);
    printf(&quot;\nThe shortest string is: % s\n&quot;, ss[k]);
}</pre> </div>

